#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

static
void kernel_2mm(int ni, int nj, int nk, int nl,
		DATA_TYPE alpha,
		DATA_TYPE beta,
		DATA_TYPE POLYBENCH_2D(tmp,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j, k;
  int vl;
  DATA_TYPE *vtmp;
  DATA_TYPE *vA;
  DATA_TYPE *vB;
  DATA_TYPE *vC;
  DATA_TYPE *vD;
  DATA_TYPE *vAlpha;
  DATA_TYPE *vBeta;
  DATA_TYPE *vOne;
  DATA_TYPE *vZero;

  // Initialize tmp to zero
  for (i = 0; i < ni; i++) {
    for (j = 0; j < nj; j++) {
      tmp[i][j] = SCALAR_VAL(0.0);
    }
  }

  // Compute tmp = alpha * A * B
  for (i = 0; i < ni; i++) {
    for (j = 0; j < nj; j++) {
      vl = __riscv_vsetvl_e32f(nk);
      vtmp = (DATA_TYPE *)__riscv_vld(vl, &tmp[i][j]);
      vA = (DATA_TYPE *)__riscv_vld(vl, &A[i][0]);
      vB = (DATA_TYPE *)__riscv_vld(vl, &B[0][j]);
      vAlpha = (DATA_TYPE *)__riscv_vld(vl, &alpha);
      vOne = (DATA_TYPE *)__riscv_vld(vl, &SCALAR_VAL(1.0));
      vZero = (DATA_TYPE *)__riscv_vld(vl, &SCALAR_VAL(0.0));

      for (k = 0; k < nk; k += vl) {
        vl = __riscv_vsetvl_e32f(nk - k);
        vA = (DATA_TYPE *)__riscv_vld(vl, &A[i][k]);
        vB = (DATA_TYPE *)__riscv_vld(vl, &B[k][j]);
        vAlpha = (DATA_TYPE *)__riscv_vld(vl, &alpha);
        vOne = (DATA_TYPE *)__riscv_vld(vl, &SCALAR_VAL(1.0));
        vZero = (DATA_TYPE *)__riscv_vld(vl, &SCALAR_VAL(0.0));

        DATA_TYPE *vProd = __riscv_vfmacc_f32m1(vl, vAlpha, vA, vB, vZero);
        vtmp = __riscv_vfadd_f32m1(vl, vtmp, vProd);
      }

      __riscv_vse(vl, vtmp, &tmp[i][j]);
    }
  }

  // Compute D = beta * D + tmp * C
  for (i = 0; i < ni; i++) {
    for (j = 0; j < nl; j++) {
      vl = __riscv_vsetvl_e32f(nj);
      vD = (DATA_TYPE *)__riscv_vld(vl, &D[i][j]);
      vBeta = (DATA_TYPE *)__riscv_vld(vl, &beta);
      vOne = (DATA_TYPE *)__riscv_vld(vl, &SCALAR_VAL(1.0));
      vZero = (DATA_TYPE *)__riscv_vld(vl, &SCALAR_VAL(0.0));

      for (k = 0; k < nj; k += vl) {
        vl = __riscv_vsetvl_e32f(nj - k);
        vD = (DATA_TYPE *)__riscv_vld(vl, &D[i][j]);
        vBeta = (DATA_TYPE *)__riscv_vld(vl, &beta);
        vOne = (DATA_TYPE *)__riscv_vld(vl, &SCALAR_VAL(1.0));
        vZero = (DATA_TYPE *)__riscv_vld(vl, &SCALAR_VAL(0.0));

        DATA_TYPE *vTmp_k = (DATA_TYPE *)__riscv_vld(vl, &tmp[i][k]);
        DATA_TYPE *vC_k = (DATA_TYPE *)__riscv_vld(vl, &C[k][j]);
        DATA_TYPE *vBeta_k = (DATA_TYPE *)__riscv_vld(vl, &beta);
        DATA_TYPE *vOne_k = (DATA_TYPE *)__riscv_vld(vl, &SCALAR_VAL(1.0));
        DATA_TYPE *vZero_k = (DATA_TYPE *)__riscv_vld(vl, &SCALAR_VAL(0.0));

        DATA_TYPE *vProd = __riscv_vfmacc_f32m1(vl, vTmp_k, vOne_k, vC_k, vZero_k);
        vD = __riscv_vfadd_f32m1(vl, vD, vProd);
      }

      __riscv_vse(vl, vD, &D[i][j]);
    }
  }
}

