static
void kernel_3mm(int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(E,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(F,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl),
		DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  int i, j, k;

#pragma scop

  // Part 1: E = A * B
  for (i = 0; i < _PB_NI; i++)
    for (j = 0; j < _PB_NJ; j++)
      {
	E[i][j] = SCALAR_VAL(0.0);
	for (k = 0; k < _PB_NK; ++k)
	  E[i][j] += A[i][k] * B[k][j];
      }

  // Vectorized Part 1: E = A * B
  // Loop order: i, k, j to vectorize over j (columns)
  for (i = 0; i < _PB_NI; i++)
    {
      DATA_TYPE *E_row = &E[i][0];
      DATA_TYPE *A_row = &A[i][0];
      for (k = 0; k < _PB_NK; k++)
	{
	  DATA_TYPE a_val = A_row[k];
	  DATA_TYPE *B_row = &B[k][0];
	  size_t vl = __riscv_vsetvl_e32m1(_PB_NJ);
	  for (j = 0; j < _PB_NJ; j += vl)
	    {
	      vl = __riscv_vsetvl_e32m1(_PB_NJ - j);
	      DATA_TYPE *b_vec = __riscv_vle32_v_a(B_row + j);
	      DATA_TYPE *prod = __riscv_vfmul_vf(b_vec, a_val, vl);
	      DATA_TYPE *acc = __riscv_vle32_v_a(E_row + j);
	      acc = __riscv_vfadd_vv(acc, prod, vl);
	      __riscv_vse32_v_a(E_row + j, acc, vl);
	    }
	}
    }

  // Part 2: F = C * D
  for (i = 0; i < _PB_NJ; i++)
    for (j = 0; j < _PB_NL; j++)
      {
	F[i][j] = SCALAR_VAL(0.0);
	for (k = 0; k < _PB_NM; ++k)
	  F[i][j] += C[i][k] * D[k][j];
      }

  // Vectorized Part 2: F = C * D
  // Loop order: i, k, j to vectorize over j (columns)
  for (i = 0; i < _PB_NJ; i++)
    {
      DATA_TYPE *F_row = &F[i][0];
      DATA_TYPE *C_row = &C[i][0];
      for (k = 0; k < _PB_NM; k++)
	{
	  DATA_TYPE c_val = C_row[k];
	  DATA_TYPE *D_row = &D[k][0];
	  size_t vl = __riscv_vsetvl_e32m1(_PB_NL);
	  for (j = 0; j < _PB_NL; j += vl)
	    {
	      vl = __riscv_vsetvl_e32m1(_PB_NL - j);
	      DATA_TYPE *d_vec = __riscv_vle32_v_a(D_row + j);
	      DATA_TYPE *prod = __riscv_vfmul_vf(d_vec, c_val, vl);
	      DATA_TYPE *acc = __riscv_vle32_v_a(F_row + j);
	      acc = __riscv_vfadd_vv(acc, prod, vl);
	      __riscv_vse32_v_a(F_row + j, acc, vl);
	    }
	}
    }

  // Part 3: G = E * F
  for (i = 0; i < _PB_NI; i++)
    for (j = 0; j < _PB_NL; j++)
      {
	G[i][j] = SCALAR_VAL(0.0);
	for (k = 0; k < _PB_NJ; ++k)
	  G[i][j] += E[i][k] * F[k][j];
      }

  // Vectorized Part 3: G = E * F
  // Loop order: i, k, j to vectorize over j (columns)
  for (i = 0; i < _PB_NI; i++)
    {
      DATA_TYPE *G_row = &G[i][0];
      DATA_TYPE *E_row = &E[i][0];
      for (k = 0; k < _PB_NJ; k++)
	{
	  DATA_TYPE e_val = E_row[k];
	  DATA_TYPE *F_row = &F[k][0];
	  size_t vl = __riscv_vsetvl_e32m1(_PB_NL);
	  for (j = 0; j < _PB_NL; j += vl)
	    {
	      vl = __riscv_vsetvl_e32m1(_PB_NL - j);
	      DATA_TYPE *f_vec = __riscv_vle32_v_a(F_row + j);
	      DATA_TYPE *prod = __riscv_vfmul_vf(f_vec, e_val, vl);
	      DATA_TYPE *acc = __riscv_vle32_v_a(G_row + j);
	      acc = __riscv_vfadd_vv(acc, prod, vl);
	      __riscv_vse32_v_a(G_row + j, acc, vl);
	    }
	}
    }
#pragma endscop

}

