static
void kernel_atax(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  int i, j;
  size_t vl;
  vuint8m1_t vzero;
  vfloat32m1_t vx, vy, vtmp, vA, vres;

  // Initialize y to 0
  vl = __riscv_vsetvl_e32m1(n);
  vzero = __riscv_vmv_v_x_u8m1(0);
  __riscv_vse_v_x_u8m1(vzero, 0, y);

  for (i = 0; i < _PB_M; i++)
    {
      // tmp[i] = 0.0
      tmp[i] = SCALAR_VAL(0.0);

      // Compute tmp[i] = sum(A[i][j] * x[j])
      vx = __riscv_vle_v_f32m1(x, vl);
      vres = __riscv_vfmv_v_f_x_f32m1(SCALAR_VAL(0.0));

      for (j = 0; j < _PB_N; j += 4)
	{
	  vA = __riscv_vle_v_f32m1(A[i] + j, vl);
	  vres = __riscv_vfadd_vv_f32m1(vres, __riscv_vfmul_vv_f32m1(vA, vx));
	}
      __riscv_vse_v_x_f32m1(vres, 0, tmp + i);

      // Update y[j] += A[i][j] * tmp[i]
      vtmp = __riscv_vfmv_v_f_x_f32m1(tmp[i]);
      vy = __riscv_vle_v_f32m1(y, vl);

      for (j = 0; j < _PB_N; j += 4)
	{
	  vA = __riscv_vle_v_f32m1(A[i] + j, vl);
	  vy = __riscv_vfadd_vv_f32m1(vy, __riscv_vfmul_vv_f32m1(vA, vtmp));
	}
      __riscv_vse_v_x_f32m1(vy, 0, y);
    }

}

