static
void kernel_bicg(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;
  size_t vl;

#pragma scop
  for (i = 0; i < _PB_M; i++)
    s[i] = 0;

  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE q_val = SCALAR_VAL(0.0);
      DATA_TYPE r_val = r[i];

      // Determine vector length based on M (number of elements to process)
      // Assuming DATA_TYPE is float (32-bit). If double, this will fail to compile,
      // but standard POLYBENCH bicg often uses float. We use the correct intrinsic for float.
      vl = __riscv_vsetvl_e32f16(_PB_M);

      // Process in chunks of vector length
      for (j = 0; j < _PB_M; j += vl)
        {
          size_t vl_actual = __riscv_vsetvl_e32f16(_PB_M - j);

          // Load A[i][j:j+vl]
          vfloat32m1_t va = __riscv_vle32_v_x(vtype(vl_actual, 0), (float*)&A[i][j]);
          // Load p[j:j+vl]
          vfloat32m1_t vp = __riscv_vle32_v_x(vtype(vl_actual, 0), (float*)&p[j]);
          // Load s[j:j+vl]
          vfloat32m1_t vs = __riscv_vle32_v_x(vtype(vl_actual, 0), (float*)&s[j]);

          // Compute r_val * va
          vfloat32m1_t vr = __riscv_vfmv_v_f_f(vtype(vl_actual, 0), r_val);
          vfloat32m1_t vtemp1 = __riscv_vfmul_vv_f_f(vtype(vl_actual, 0), vr, va);

          // Accumulate to s
          vs = __riscv_vfadd_vv_f_f(vtype(vl_actual, 0), vs, vtemp1);
          __riscv_vse32_v_x(vtype(vl_actual, 0), vs, (float*)&s[j]);

          // Compute va * vp
          vfloat32m1_t vtemp2 = __riscv_vfmul_vv_f_f(vtype(vl_actual, 0), va, vp);

          // Accumulate vector elements to scalar q_val
          // Since there is no direct "vector sum to scalar" intrinsic in the basic set,
          // we iterate over the vector elements.
          for (int k = 0; k < vl_actual; k++)
            {
              q_val += __riscv_vle32_m_x(vtype(vl_actual, 0), vtemp2, k);
            }
        }

      q[i] = q_val;
    }
#pragma endscop
}

