static
void kernel_cholesky(int n,
		     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;
  size_t vl;
  vuint8mf8_t mask;
  vfloat32mf8_t vAij, vAik, vAj, vAik_sq, vAik_sq_sum;
  vfloat32mf8_t vone, vzero;

  vone = __riscv_vfmv_v_f_x(1.0f);
  vzero = __riscv_vfmv_v_f_x(0.0f);

#pragma scop
  for (i = 0; i < _PB_N; i++) {

     for (j = 0; j < i; j++) {
        DATA_TYPE Aij = A[i][j];
        DATA_TYPE Aj = A[j][j];

        if (Aj == 0.0f) {
           A[i][j] = 0.0f;
           continue;
        }

        vl = __riscv_vsetvl_e8m1(i);
        mask = __riscv_vmv_v_x_u8m1(vl);

        vAij = __riscv_vleif_v_f8m1(mask, A[i]);
        vAj = __riscv_vleif_v_f8m1(mask, A[j]);

        vAik_sq_sum = vzero;

        for (k = 0; k < j; k++) {
           vAik = __riscv_vleif_v_f8m1(mask, A[i]);
           vAik_sq = __riscv_vfmul_vv_f8m1(vAik, vAik);
           vAik_sq_sum = __riscv_vfadd_vv_f8m1(vAik_sq_sum, vAik_sq);
        }

        vAij = __riscv_vfmul_vf_f8m1(vAij, vAj);
        vAij = __riscv_vfsub_vf_f8m1(vAij, vAik_sq_sum);

        __riscv_vseif_v_f8m1(mask, vAij, A[i]);

        A[i][j] = __riscv_vfmv_f_x_u8m1(vAij);
        A[i][j] /= Aj;
     }

     for (k = 0; k < i; k++) {
        A[i][i] -= A[i][k] * A[i][k];
     }
     A[i][i] = SQRT_FUN(A[i][i]);
  }
#pragma endscop

}

