static
void kernel_correlation(int m, int n,
			DATA_TYPE float_n,
			DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
			DATA_TYPE POLYBENCH_2D(corr,M,M,m,m),
			DATA_TYPE POLYBENCH_1D(mean,M,m),
			DATA_TYPE POLYBENCH_1D(stddev,M,m))
{
  int i, j, k;
  DATA_TYPE eps = SCALAR_VAL(0.1);
  DATA_TYPE sqrt_float_n = SQRT_FUN(float_n);

#pragma scop
  // Use the macro values directly as intended by the polybench framework
  // Avoid redefining M and N as local variables which conflicts with macros
  for (j = 0; j < _PB_M; j++)
    {
      mean[j] = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_N; i++)
	mean[j] += data[i][j];
      mean[j] /= float_n;
    }

  for (j = 0; j < _PB_M; j++)
    {
      DATA_TYPE sum_sq = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_N; i++)
        sum_sq += (data[i][j] - mean[j]) * (data[i][j] - mean[j]);
      stddev[j] = SQRT_FUN(sum_sq / float_n);
      stddev[j] = stddev[j] <= eps ? SCALAR_VAL(1.0) : stddev[j];
    }

  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE inv_std = SCALAR_VAL(1.0) / (sqrt_float_n * stddev[i]);
      for (j = 0; j < _PB_M; j++)
        data[i][j] = (data[i][j] - mean[j]) * inv_std;
    }

  for (i = 0; i < _PB_M-1; i++)
    {
      corr[i][i] = SCALAR_VAL(1.0);
      for (j = i+1; j < _PB_M; j++)
        {
          DATA_TYPE sum = SCALAR_VAL(0.0);
          for (k = 0; k < _PB_N; k++)
            sum += (data[k][i] * data[k][j]);
          corr[i][j] = sum;
          corr[j][i] = sum;
        }
    }
  corr[_PB_M-1][_PB_M-1] = SCALAR_VAL(1.0);
#pragma endscop
}

