static
void kernel_covariance(int m, int n,
		       DATA_TYPE float_n,
		       DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
		       DATA_TYPE POLYBENCH_2D(cov,M,M,m,m),
		       DATA_TYPE POLYBENCH_1D(mean,M,m))
{
  int i, j, k;
  float_t vzero, vone, vmean, vdata_i, vdata_j, vprod, vsum;
  size_t vl;

  vl = vsetvl_e32f(m);

#pragma scop
  // Compute mean
  for (j = 0; j < _PB_M; j++)
    {
      mean[j] = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_N; i++)
        mean[j] += data[i][j];
      mean[j] /= float_n;
    }

  // Subtract mean from data
  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      data[i][j] -= mean[j];

  // Compute covariance
  vzero = __riscv_vfmv_v_f_x(vl, SCALAR_VAL(0.0));
  vone = __riscv_vfmv_v_f_x(vl, SCALAR_VAL(1.0));

  for (i = 0; i < _PB_M; i++)
    {
      for (j = i; j < _PB_M; j++)
        {
          vsum = vzero;
          for (k = 0; k < _PB_N; k++)
            {
              vdata_i = __riscv_vleif_v_f_x(vl, (float*)&data[k][i]);
              vdata_j = __riscv_vleif_v_f_x(vl, (float*)&data[k][j]);
              vprod = __riscv_vfmul_vv(vl, vdata_i, vdata_j);
              vsum = __riscv_vfadd_vv(vl, vsum, vprod);
            }
          cov[i][j] = __riscv_vfmv_f_x(vl, vsum) / (float_n - SCALAR_VAL(1.0));
          cov[j][i] = cov[i][j];
        }
    }
#pragma endscop

}

