static
void kernel_deriche(int w, int h, DATA_TYPE alpha,
       DATA_TYPE POLYBENCH_2D(imgIn, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(imgOut, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y1, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y2, W, H, w, h)) {
    int i, j;
    DATA_TYPE xm1, tm1, ym1, ym2;
    DATA_TYPE xp1, xp2;
    DATA_TYPE tp1, tp2;
    DATA_TYPE yp1, yp2;

    DATA_TYPE k;
    DATA_TYPE a1, a2, a3, a4, a5, a6, a7, a8;
    DATA_TYPE b1, b2, c1, c2;

    // Precompute constants outside the loop
    k = (SCALAR_VAL(1.0)-EXP_FUN(-alpha))*(SCALAR_VAL(1.0)-EXP_FUN(-alpha))/(SCALAR_VAL(1.0)+SCALAR_VAL(2.0)*alpha*EXP_FUN(-alpha)-EXP_FUN(SCALAR_VAL(2.0)*alpha));
    a1 = a5 = k;
    a2 = a6 = k*EXP_FUN(-alpha)*(alpha-SCALAR_VAL(1.0));
    a3 = a7 = k*EXP_FUN(-alpha)*(alpha+SCALAR_VAL(1.0));
    a4 = a8 = -k*EXP_FUN(SCALAR_VAL(-2.0)*alpha);
    b1 =  POW_FUN(SCALAR_VAL(2.0),-alpha);
    b2 = -EXP_FUN(SCALAR_VAL(-2.0)*alpha);
    c1 = c2 = 1;

    // Define vector length
    #if defined(__riscv_vector)
    #define VLEN (vlen/sizeof(DATA_TYPE))
    #else
    #define VLEN 1
    #endif

    // First pass: Horizontal filtering
    for (i=0; i<w; i++) {
        DATA_TYPE *in_row = (DATA_TYPE*)imgIn + i*W;
        DATA_TYPE *y1_row = (DATA_TYPE*)y1 + i*W;
        DATA_TYPE *y2_row = (DATA_TYPE*)y2 + i*W;

        xm1 = SCALAR_VAL(0.0);
        ym1 = SCALAR_VAL(0.0);
        ym2 = SCALAR_VAL(0.0);

        int vlen = VLEN;
        int remaining = w;
        int start = 0;

        while (remaining > 0) {
            int vlen_use = (remaining < vlen) ? remaining : vlen;
            int end = start + vlen_use;

            if (vlen_use >= vlen) {
                // Vectorized computation
                vfloat_t v_in, v_y1, v_y2;
                vfloat_t v_a1, v_a2, v_b1, v_b2;
                vfloat_t v_xm1, v_ym1, v_ym2;
                vfloat_t v_out;

                v_a1 = vfloat_from_array(&a1, vlen);
                v_a2 = vfloat_from_array(&a2, vlen);
                v_b1 = vfloat_from_array(&b1, vlen);
                v_b2 = vfloat_from_array(&b2, vlen);
                v_xm1 = vfloat_from_array(&xm1, vlen);
                v_ym1 = vfloat_from_array(&ym1, vlen);
                v_ym2 = vfloat_from_array(&ym2, vlen);

                v_in = vfloat_from_array(in_row + start, vlen);
                v_out = v_a1 * v_in + v_a2 * v_xm1 + v_b1 * v_ym1 + v_b2 * v_ym2;
                vfloat_store(y1_row + start, v_out);

                // Update state for next iteration
                xm1 = imgIn[i][end-1];
                ym1 = y1[i][end-1];
                ym2 = ym1;
            } else {
                // Scalar fallback for remaining elements
                for (j = start; j < end; j++) {
                    y1[i][j] = a1*imgIn[i][j] + a2*xm1 + b1*ym1 + b2*ym2;
                    xm1 = imgIn[i][j];
                    ym2 = ym1;
                    ym1 = y1[i][j];
                }
            }

            start = end;
            remaining -= vlen_use;
        }
    }

    // Second pass: Horizontal filtering (reverse)
    for (i=0; i<w; i++) {
        DATA_TYPE *in_row = (DATA_TYPE*)imgIn + i*W;
        DATA_TYPE *y2_row = (DATA_TYPE*)y2 + i*W;

        yp1 = SCALAR_VAL(0.0);
        yp2 = SCALAR_VAL(0.0);
        xp1 = SCALAR_VAL(0.0);
        xp2 = SCALAR_VAL(0.0);

        int vlen = VLEN;
        int remaining = w;
        int start = w - 1;

        while (remaining > 0) {
            int vlen_use = (remaining < vlen) ? remaining : vlen;
            int end = start - vlen_use;

            if (vlen_use >= vlen) {
                // Vectorized computation
                vfloat_t v_in, v_y2;
                vfloat_t v_a3, v_a4, v_b1, v_b2;
                vfloat_t v_xp1, v_yp1, v_yp2;
                vfloat_t v_out;

                v_a3 = vfloat_from_array(&a3, vlen);
                v_a4 = vfloat_from_array(&a4, vlen);
                v_b1 = vfloat_from_array(&b1, vlen);
                v_b2 = vfloat_from_array(&b2, vlen);
                v_xp1 = vfloat_from_array(&xp1, vlen);
                v_yp1 = vfloat_from_array(&yp1, vlen);
                v_yp2 = vfloat_from_array(&yp2, vlen);

                v_in = vfloat_from_array(in_row + start, vlen);
                v_out = v_a3 * v_xp1 + v_a4 * v_xp2 + v_b1 * v_yp1 + v_b2 * v_yp2;
                vfloat_store(y2_row + start, v_out);

                // Update state for next iteration
                xp2 = xp1;
                xp1 = imgIn[i][end];
                yp2 = yp1;
                yp1 = y2[i][end];
            } else {
                // Scalar fallback for remaining elements
                for (j = start; j >= end; j--) {
                    y2[i][j] = a3*xp1 + a4*xp2 + b1*yp1 + b2*yp2;
                    xp2 = xp1;
                    xp1 = imgIn[i][j];
                    yp2 = yp1;
                    yp1 = y2[i][j];
                }
            }

            start = end;
            remaining -= vlen_use;
        }
    }

    // Combine results
    for (i=0; i<w; i++) {
        for (j=0; j<h; j++) {
            imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
        }
    }

    // Third pass: Vertical filtering (forward)
    for (j=0; j<h; j++) {
        DATA_TYPE *out_col = (DATA_TYPE*)imgOut + j*w;
        DATA_TYPE *y1_col = (DATA_TYPE*)y1 + j*w;

        tm1 = SCALAR_VAL(0.0);
        ym1 = SCALAR_VAL(0.0);
        ym2 = SCALAR_VAL(0.0);

        int vlen = VLEN;
        int remaining = w;
        int start = 0;

        while (remaining > 0) {
            int vlen_use = (remaining < vlen) ? remaining : vlen;
            int end = start + vlen_use;

            if (vlen_use >= vlen) {
                // Vectorized computation
                vfloat_t v_out, v_y1;
                vfloat_t v_a5, v_a6, v_b1, v_b2;
                vfloat_t v_tm1, v_ym1, v_ym2;
                vfloat_t v_res;

                v_a5 = vfloat_from_array(&a5, vlen);
                v_a6 = vfloat_from_array(&a6, vlen);
                v_b1 = vfloat_from_array(&b1, vlen);
                v_b2 = vfloat_from_array(&b2, vlen);
                v_tm1 = vfloat_from_array(&tm1, vlen);
                v_ym1 = vfloat_from_array(&ym1, vlen);
                v_ym2 = vfloat_from_array(&ym2, vlen);

                v_out = vfloat_from_array(out_col + start, vlen);
                v_res = v_a5 * v_out + v_a6 * v_tm1 + v_b1 * v_ym1 + v_b2 * v_ym2;
                vfloat_store(y1_col + start, v_res);

                // Update state for next iteration
                tm1 = imgOut[start + vlen_use - 1];
                ym1 = y1[start + vlen_use - 1];
                ym2 = ym1;
            } else {
                // Scalar fallback for remaining elements
                for (i = start; i < end; i++) {
                    y1[i][j] = a5*imgOut[i][j] + a6*tm1 + b1*ym1 + b2*ym2;
                    tm1 = imgOut[i][j];
                    ym2 = ym1;
                    ym1 = y1[i][j];
                }
            }

            start = end;
            remaining -= vlen_use;
        }
    }

    // Fourth pass: Vertical filtering (reverse)
    for (j=0; j<h; j++) {
        DATA_TYPE *out_col = (DATA_TYPE*)imgOut + j*w;
        DATA_TYPE *y2_col = (DATA_TYPE*)y2 + j*w;

        tp1 = SCALAR_VAL(0.0);
        tp2 = SCALAR_VAL(0.0);
        yp1 = SCALAR_VAL(0.0);
        yp2 = SCALAR_VAL(0.0);

        int vlen = VLEN;
        int remaining = w;
        int start = w - 1;

        while (remaining > 0) {
            int vlen_use = (remaining < vlen) ? remaining : vlen;
            int end = start - vlen_use;

            if (vlen_use >= vlen) {
                // Vectorized computation
                vfloat_t v_out, v_y2;
                vfloat_t v_a7, v_a8, v_b1, v_b2;
                vfloat_t v_tp1, v_yp1, v_yp2;
                vfloat_t v_res;

                v_a7 = vfloat_from_array(&a7, vlen);
                v_a8 = vfloat_from_array(&a8, vlen);
                v_b1 = vfloat_from_array(&b1, vlen);
                v_b2 = vfloat_from_array(&b2, vlen);
                v_tp1 = vfloat_from_array(&tp1, vlen);
                v_yp1 = vfloat_from_array(&yp1, vlen);
                v_yp2 = vfloat_from_array(&yp2, vlen);

                v_out = vfloat_from_array(out_col + start, vlen);
                v_res = v_a7 * v_tp1 + v_a8 * v_tp2 + v_b1 * v_yp1 + v_b2 * v_yp2;
                vfloat_store(y2_col + start, v_res);

                // Update state for next iteration
                tp2 = tp1;
                tp1 = imgOut[end];
                yp2 = yp1;
                yp1 = y2[end];
            } else {
                // Scalar fallback for remaining elements
                for (i = start; i >= end; i--) {
                    y2[i][j] = a7*tp1 + a8*tp2 + b1*yp1 + b2*yp2;
                    tp2 = tp1;
                    tp1 = imgOut[i][j];
                    yp2 = yp1;
                    yp1 = y2[i][j];
                }
            }

            start = end;
            remaining -= vlen_use;
        }
    }

    // Final combine
    for (i=0; i<w; i++) {
        for (j=0; j<h; j++) {
            imgOut[i][j] = c2*(y1[i][j] + y2[i][j]);
        }
    }
}

