static
void kernel_durbin(int n,
		   DATA_TYPE POLYBENCH_1D(r,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
 DATA_TYPE z[N];
 DATA_TYPE alpha;
 DATA_TYPE beta;
 DATA_TYPE sum;

 int i,k;

#pragma scop
 y[0] = -r[0];
 beta = SCALAR_VAL(1.0);
 alpha = -r[0];

 for (k = 1; k < _PB_N; k++) {
   beta = (1-alpha*alpha)*beta;
   sum = SCALAR_VAL(0.0);

   // Inner loop: sum += r[k-i-1]*y[i] for i=0..k-1
   // This is a dot product of r[0..k-1] and y[0..k-1]
   if (k >= 16) {
      vfloat32_t vr = __riscv_vle_v_f32m1(r, k);
      vfloat32_t vy = __riscv_vle_v_f32m1(y, k);
      vfloat32_t vsum = __riscv_vf_v_f32m1(vy, vr, vm_v_ff);
      vfloat32_t vzero = __riscv_vfmv_v_f_f(vfloat32_m(0.0));
      vsum = __riscv_vfadd_vv_f32m1(vsum, vzero);
      sum = __riscv_vfmv_f_f_f32m1(vsum);
   } else {
      for (i=0; i<k; i++) {
         sum += r[k-i-1]*y[i];
      }
   }
   alpha = - (r[k] + sum)/beta;

   // Inner loop: z[i] = y[i] + alpha*y[k-i-1] for i=0..k-1
   if (k >= 16) {
      vfloat32_t vy = __riscv_vle_v_f32m1(y, k);
      vfloat32_t valpha = __riscv_vfmv_v_f_f(vfloat32_m(alpha));

      // Compute y[k-i-1] for i=0..k-1, which is y[k-1], y[k-2], ..., y[0]
      // This is a reverse of y[0..k-1]
      vfloat32_t vy_rev = __riscv_vrev_vv_f32m1(vy, vzero);
      vfloat32_t vterm = __riscv_vfmul_vv_f32m1(vy_rev, valpha);
      vfloat32_t vz = __riscv_vfadd_vv_f32m1(vy, vterm);
      __riscv_vse_v_f32m1(z, k, vz);
   } else {
      for (i=0; i<k; i++) {
         z[i] = y[i] + alpha*y[k-i-1];
      }
   }

   // Copy z[0..k-1] to y[0..k-1]
   if (k >= 16) {
      vfloat32_t vz = __riscv_vle_v_f32m1(z, k);
      __riscv_vse_v_f32m1(y, k, vz);
   } else {
      for (i=0; i<k; i++) {
         y[i] = z[i];
      }
   }
   y[k] = alpha;
 }
#pragma endscop
}

