static
void kernel_fdtd_2d(int tmax,
		    int nx,
		    int ny,
		    DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  int t, i, j;
  size_t vl;
  vfloat32m1_t vzero;
  vfloat32m1_t vhalf, vseven_tenth;

  #if defined(__riscv_vector)
  vzero = vmv_v_f32_m1(0.0f);
  vhalf = vmov_n_f32(0.5f);
  vseven_tenth = vmov_n_f32(0.7f);
  #endif

  for(t = 0; t < _PB_TMAX; t++)
    {
      // Initialize ey[0][j] = _fict_[t]
      for (j = 0; j < _PB_NY; j++)
	ey[0][j] = _fict_[t];

      // Update ey[i][j] for i = 1 to NX-1
      // ey[i][j] = ey[i][j] - 0.5 * (hz[i][j] - hz[i-1][j])
      for (i = 1; i < _PB_NX; i++)
	{
	  #if defined(__riscv_vector)
	  vl = vsetvl_e32m1(_PB_NY);
	  vfloat32m1_t *v_ey = (vfloat32m1_t *)&ey[i][0];
	  vfloat32m1_t *v_hz = (vfloat32m1_t *)&hz[i][0];
	  vfloat32m1_t *v_hz_next = (vfloat32m1_t *)&hz[i-1][0];
	  vfloat32m1_t v_diff = vsub_vv_f32m1(v_hz, v_hz_next, vl);
	  v_ey = vsub_vv_f32m1(v_ey, vmul_vv_f32m1(vhalf, v_diff, vl), vl);
	  #else
	  for (j = 0; j < _PB_NY; j++)
	    ey[i][j] = ey[i][j] - SCALAR_VAL(0.5)*(hz[i][j]-hz[i-1][j]);
	  #endif
	}

      // Update ex[i][j] for j = 1 to NY-1
      // ex[i][j] = ex[i][j] - 0.5 * (hz[i][j] - hz[i][j-1])
      for (i = 0; i < _PB_NX; i++)
	{
	  #if defined(__riscv_vector)
	  vl = vsetvl_e32m1(_PB_NY);
	  vfloat32m1_t *v_ex = (vfloat32m1_t *)&ex[i][0];
	  vfloat32m1_t *v_hz = (vfloat32m1_t *)&hz[i][0];
	  // Create v_prev where v_prev[j] = hz[i][j-1], and v_prev[0] = 0
	  vfloat32m1_t v_prev = vslide1up_vx_f32m1(v_hz, vzero, vl);
	  vfloat32m1_t v_diff = vsub_vv_f32m1(v_hz, v_prev, vl);
	  v_ex = vsub_vv_f32m1(v_ex, vmul_vv_f32m1(vhalf, v_diff, vl), vl);
	  #else
	  for (j = 1; j < _PB_NY; j++)
	    ex[i][j] = ex[i][j] - SCALAR_VAL(0.5)*(hz[i][j]-hz[i][j-1]);
	  #endif
	}

      // Update hz[i][j] for i = 0 to NX-2, j = 0 to NY-2
      // hz[i][j] = hz[i][j] - 0.7 * (ex[i][j+1] - ex[i][j] + ey[i+1][j] - ey[i][j])
      for (i = 0; i < _PB_NX - 1; i++)
	{
	  #if defined(__riscv_vector)
	  vl = vsetvl_e32m1(_PB_NY - 1);
	  vfloat32m1_t *v_ex = (vfloat32m1_t *)&ex[i][0];
	  vfloat32m1_t *v_ex_next = (vfloat32m1_t *)&ex[i+1][0];
	  vfloat32m1_t *v_ey = (vfloat32m1_t *)&ey[i][0];
	  vfloat32m1_t *v_ey_next = (vfloat32m1_t *)&ey[i+1][0];
	  vfloat32m1_t *v_hz = (vfloat32m1_t *)&hz[i][0];
	  vfloat32m1_t v_diff_ex = vsub_vv_f32m1(v_ex_next, v_ex, vl);
	  vfloat32m1_t v_diff_ey = vsub_vv_f32m1(v_ey_next, v_ey, vl);
	  vfloat32m1_t v_sum = vadd_vv_f32m1(v_diff_ex, v_diff_ey, vl);
	  v_hz = vsub_vv_f32m1(v_hz, vmul_vv_f32m1(vseven_tenth, v_sum, vl), vl);
	  #else
	  for (j = 0; j < _PB_NY - 1; j++)
	    hz[i][j] = hz[i][j] - SCALAR_VAL(0.7)*  (ex[i][j+1] - ex[i][j] +
						       ey[i+1][j] - ey[i][j]);
	  #endif
	}
    }
}

