static
void kernel_floyd_warshall(int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;
  size_t vl;

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      for(i = 0; i < _PB_N; i++)
	{
	  vl = vsetvl_e32f(n, n);
	  vfloat32m1_t path_i_k = vle32_fv((float*)path[i] + k, vl);
	  vfloat32m1_t path_k_j = vle32_fv((float*)path[k] + 0, vl);
	  vfloat32m1_t path_ij = vle32_fv((float*)path[i] + 0, vl);
	  vfloat32m1_t sum = vadd_fv(path_i_k, path_k_j);
	  vfloat32m1_t min = vmin_fv(path_ij, sum);
	  vst32_fv((float*)path[i] + 0, min, vl);
	}
    }
#pragma endscop

}

