static
void kernel_gemm(int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j, k;
  int vl = 0;

#pragma scop
  for (i = 0; i < _PB_NI; i++) {
    // C[i][j] *= beta
    for (j = 0; j < _PB_NJ; j += vl) {
      vl = __riscv_vsetvl_e32m1(vl);
      vfloat32m1_t vc = __riscv_vle_v_f(vl, (vfloat32m1_t*)&C[i][j]);
      vc = __riscv_vfmul_vv_f_f(vc, __riscv_vfmv_v_f(vl, beta));
      __riscv_vse_v_f(vc, (vfloat32m1_t*)&C[i][j]);
    }

    // C[i][j] += alpha * A[i][k] * B[k][j]
    for (k = 0; k < _PB_NK; k++) {
      DATA_TYPE a_val = A[i][k];
      vfloat32m1_t va = __riscv_vfmv_v_f(vl, a_val);
      vfloat32m1_t valpha = __riscv_vfmv_v_f(vl, alpha);

      for (j = 0; j < _PB_NJ; j += vl) {
        vl = __riscv_vsetvl_e32m1(vl);
        vfloat32m1_t vb = __riscv_vle_v_f(vl, (vfloat32m1_t*)&B[k][j]);
        vfloat32m1_t vtemp = __riscv_vfmul_vv_f_f(vb, va);
        vtemp = __riscv_vfmul_vv_f_f(vtemp, valpha);
        vfloat32m1_t vc = __riscv_vle_v_f(vl, (vfloat32m1_t*)&C[i][j]);
        vc = __riscv_vfadd_vv_f_f(vc, vtemp);
        __riscv_vse_v_f(vc, (vfloat32m1_t*)&C[i][j]);
      }
    }
  }
#pragma endscop
}

