static
void kernel_gemver(int n,
		   DATA_TYPE alpha,
		   DATA_TYPE beta,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(u1,N,n),
		   DATA_TYPE POLYBENCH_1D(v1,N,n),
		   DATA_TYPE POLYBENCH_1D(u2,N,n),
		   DATA_TYPE POLYBENCH_1D(v2,N,n),
		   DATA_TYPE POLYBENCH_1D(w,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n),
		   DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;
  size_t vl;
  vfloat32m1_t v_u1, v_v1, v_u2, v_v2, v_x, v_y, v_z, v_w, v_A_row, v_A_col, v_temp;

#pragma scop

  // Determine vector length based on n
  vl = __riscv_vsetvl_e32m1(n);
  int vlen = __riscv_vget_vl();

  // Loop 1: A[i][j] = A[i][j] + u1[i] * v1[j] + u2[i] * v2[j]
  for (i = 0; i < _PB_N; i += vlen) {
    size_t vl_i = __riscv_vsetvl_e32m1(vlen - (i < vlen ? i : 0));
    v_u1 = __riscv_vle32_v_f32m1((const DATA_TYPE*)(&u1[i]), vl_i);
    v_u2 = __riscv_vle32_v_f32m1((const DATA_TYPE*)(&u2[i]), vl_i);

    for (j = 0; j < _PB_N; j += vlen) {
      size_t vl_j = __riscv_vsetvl_e32m1(vlen - (j < vlen ? j : 0));
      v_v1 = __riscv_vle32_v_f32m1((const DATA_TYPE*)(&v1[j]), vl_j);
      v_v2 = __riscv_vle32_v_f32m1((const DATA_TYPE*)(&v2[j]), vl_j);

      v_A_row = __riscv_vle32_v_f32m1((const DATA_TYPE*)(&A[i][j]), vl_j);
      v_temp = __riscv_vmul_vv(v_u1, v_v1, vl_j);
      v_temp = __riscv_vfadd_vv(v_temp, v_A_row, vl_j);
      v_temp = __riscv_vmul_vv(v_u2, v_v2, vl_j);
      v_temp = __riscv_vfadd_vv(v_temp, v_temp, vl_j);

      __riscv_vse32_v_f32m1((DATA_TYPE*)(&A[i][j]), v_temp, vl_j);
    }
  }

  // Loop 2: x[i] = x[i] + beta * A[j][i] * y[j]
  for (i = 0; i < _PB_N; i += vlen) {
    size_t vl_i = __riscv_vsetvl_e32m1(vlen - (i < vlen ? i : 0));
    v_x = __riscv_vle32_v_f32m1((const DATA_TYPE*)(&x[i]), vl_i);
    v_y = __riscv_vle32_v_f32m1((const DATA_TYPE*)(&y[i]), vl_i);

    for (j = 0; j < _PB_N; j += vlen) {
      size_t vl_j = __riscv_vsetvl_e32m1(vlen - (j < vlen ? j : 0));
      v_A_col = __riscv_vle32_v_f32m1((const DATA_TYPE*)(&A[j][i]), vl_j);
      v_temp = __riscv_vmul_vv(v_A_col, v_y, vl_j);
      v_temp = __riscv_vfmul_sx_vv(v_temp, beta, vl_j);
      v_temp = __riscv_vfadd_vv(v_x, v_temp, vl_j);
      __riscv_vse32_v_f32m1((DATA_TYPE*)(&x[i]), v_temp, vl_j);
    }
  }

  // Loop 3: x[i] = x[i] + z[i]
  for (i = 0; i < _PB_N; i += vlen) {
    size_t vl_i = __riscv_vsetvl_e32m1(vlen - (i < vlen ? i : 0));
    v_x = __riscv_vle32_v_f32m1((const DATA_TYPE*)(&x[i]), vl_i);
    v_z = __riscv_vle32_v_f32m1((const DATA_TYPE*)(&z[i]), vl_i);
    v_x = __riscv_vfadd_vv(v_x, v_z, vl_i);
    __riscv_vse32_v_f32m1((DATA_TYPE*)(&x[i]), v_x, vl_i);
  }

  // Loop 4: w[i] = w[i] + alpha * A[i][j] * x[j]
  for (i = 0; i < _PB_N; i += vlen) {
    size_t vl_i = __riscv_vsetvl_e32m1(vlen - (i < vlen ? i : 0));
    v_w = __riscv_vle32_v_f32m1((const DATA_TYPE*)(&w[i]), vl_i);
    v_x = __riscv_vle32_v_f32m1((const DATA_TYPE*)(&x[i]), vl_i);

    for (j = 0; j < _PB_N; j += vlen) {
      size_t vl_j = __riscv_vsetvl_e32m1(vlen - (j < vlen ? j : 0));
      v_A_row = __riscv_vle32_v_f32m1((const DATA_TYPE*)(&A[i][j]), vl_j);
      v_temp = __riscv_vmul_vv(v_A_row, v_x, vl_j);
      v_temp = __riscv_vfmul_sx_vv(v_temp, alpha, vl_j);
      v_temp = __riscv_vfadd_vv(v_w, v_temp, vl_j);
      __riscv_vse32_v_f32m1((DATA_TYPE*)(&w[i]), v_temp, vl_j);
    }
  }

#pragma endscop
}

