static
void kernel_gesummv(int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		    DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;
  int vl;
  vfloat32m1_t vtmp;
  vfloat32m1_t vy;
  vfloat32m1_t vx;
  vfloat32m1_t va;
  vfloat32m1_t vb;
  vfloat32m1_t valpha;
  vfloat32m1_t vbeta;
  vfloat32m1_t vone;
  vfloat32m1_t vzero;

  vl = __riscv_vsetvl_e32m1(n);
  vtmp = __riscv_vfmv_v_f(vzero);
  vy = __riscv_vfmv_v_f(vzero);
  vx = __riscv_vfmv_v_f(vzero);
  va = __riscv_vfmv_v_f(vzero);
  vb = __riscv_vfmv_v_f(vzero);
  valpha = __riscv_vfmv_v_f(vzero);
  vbeta = __riscv_vfmv_v_f(vzero);
  vone = __riscv_vfmv_v_f(vzero);
  vzero = __riscv_vfmv_v_f(vzero);

  for (i = 0; i < n; i += vl)
    {
      int vm = __riscv_vsetvl_e32m1(vl);
      vtmp = __riscv_vfmv_v_f(vzero);
      vy = __riscv_vfmv_v_f(vzero);
      vx = __riscv_vfmv_v_f(vzero);
      va = __riscv_vfmv_v_f(vzero);
      vb = __riscv_vfmv_v_f(vzero);
      valpha = __riscv_vfmv_v_f(vzero);
      vbeta = __riscv_vfmv_v_f(vzero);
      vone = __riscv_vfmv_v_f(vzero);
      vzero = __riscv_vfmv_v_f(vzero);

      for (j = 0; j < n; j += vm)
	{
	  int vlen = __riscv_vsetvl_e32m1(vm);
	  vtmp = __riscv_vfmv_v_f(vzero);
	  vy = __riscv_vfmv_v_f(vzero);
	  vx = __riscv_vfmv_v_f(vzero);
	  va = __riscv_vfmv_v_f(vzero);
	  vb = __riscv_vfmv_v_f(vzero);
	  valpha = __riscv_vfmv_v_f(vzero);
	  vbeta = __riscv_vfmv_v_f(vzero);
	  vone = __riscv_vfmv_v_f(vzero);
	  vzero = __riscv_vfmv_v_f(vzero);

	  for (int k = 0; k < vm; k += vlen)
	    {
	      int vl = __riscv_vsetvl_e32m1(vl);
	      vtmp = __riscv_vfmv_v_f(vzero);
	      vy = __riscv_vfmv_v_f(vzero);
	      vx = __riscv_vfmv_v_f(vzero);
	      va = __riscv_vfmv_v_f(vzero);
	      vb = __riscv_vfmv_v_f(vzero);
	      valpha = __riscv_vfmv_v_f(vzero);
	      vbeta = __riscv_vfmv_v_f(vzero);
	      vone = __riscv_vfmv_v_f(vzero);
	      vzero = __riscv_vfmv_v_f(vzero);

	      for (int l = 0; l < vl; l++)
		{
		  int idx = i + l;
		  int jdx = j + l;
		  tmp[idx] = A[idx][jdx] * x[jdx] + tmp[idx];
		  y[idx] = B[idx][jdx] * x[jdx] + y[idx];
		}
	    }
	}
    }
}

