static
void kernel_gramschmidt(int m, int n,
			DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
			DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
			DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j, k;
  DATA_TYPE nrm;
  DATA_TYPE *v_a_col;
  DATA_TYPE *v_q_col;
  DATA_TYPE *v_r_row;
  DATA_TYPE *v_a_row;
  DATA_TYPE *v_q_row;
  DATA_TYPE *v_r_val;
  DATA_TYPE *v_nrm;
  DATA_TYPE *v_one;
  DATA_TYPE *v_zero;
  DATA_TYPE *v_temp;
  DATA_TYPE *v_sq;
  DATA_TYPE *v_sqrt;
  DATA_TYPE *v_div;
  DATA_TYPE *v_sub;
  DATA_TYPE *v_add;

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      nrm = SCALAR_VAL(0.0);
      v_nrm = __riscv_vfmv_v_f_f(SCALAR_VAL(0.0));

      v_a_col = (DATA_TYPE *)&A[0][k];
      v_q_col = (DATA_TYPE *)&Q[0][k];
      v_r_row = (DATA_TYPE *)&R[k];
      v_a_row = (DATA_TYPE *)&A[0][k];
      v_q_row = (DATA_TYPE *)&Q[0][k];
      v_r_val = (DATA_TYPE *)&R[k][k];

      for (i = 0; i < _PB_M; i++)
        {
          nrm += v_a_col[i] * v_a_col[i];
          v_nrm = __riscv_vfmadd_v_f_f(v_nrm, v_a_col[i], v_a_col[i]);
        }

      v_sqrt = __riscv_vsqrt_f_f(v_nrm);
      v_div = __riscv_vdiv_v_f_f(v_a_col, v_sqrt);
      for (i = 0; i < _PB_M; i++)
        Q[i][k] = v_div[i];

      v_r_row = (DATA_TYPE *)&R[k];
      v_r_val = (DATA_TYPE *)&R[k][k];
      v_r_row[k] = v_sqrt[0];

      for (j = k + 1; j < _PB_N; j++)
	{
	  R[k][j] = SCALAR_VAL(0.0);
	  v_r_row[j] = v_zero[0];
	  v_a_row = (DATA_TYPE *)&A[0][j];
	  v_q_col = (DATA_TYPE *)&Q[0][k];
	  v_r_val = (DATA_TYPE *)&R[k][j];
	  v_temp = __riscv_vfmv_v_f_f(SCALAR_VAL(0.0));

	  for (i = 0; i < _PB_M; i++)
	    {
	      v_temp = __riscv_vfmadd_v_f_f(v_temp, v_q_col[i], v_a_row[i]);
	      v_r_val[i] = v_temp;
	    }

	  v_a_row = (DATA_TYPE *)&A[0][j];
	  v_q_col = (DATA_TYPE *)&Q[0][k];
	  v_r_val = (DATA_TYPE *)&R[k][j];
	  v_temp = __riscv_vfmv_v_f_f(SCALAR_VAL(0.0));
	  for (i = 0; i < _PB_M; i++)
	    {
	      v_temp = __riscv_vfmadd_v_f_f(v_temp, v_q_col[i], v_r_val[i]);
	      v_a_row[i] = v_a_row[i] - v_temp;
	    }
	}
    }
#pragma endscop

}

