static
void kernel_heat_3d(int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		      DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int t, i, j;
  int stride_j = n;
  int stride_i = n * n;

  DATA_TYPE one_eighth = SCALAR_VAL(0.125);
  DATA_TYPE one_quarter = SCALAR_VAL(0.25);

  for (t = 1; t <= tsteps; t++) {
      // Compute B from A
      for (i = 1; i < n; i++) {
          DATA_TYPE *a_ptr = (DATA_TYPE*)(A + (i-1)*stride_i);
          DATA_TYPE *b_ptr = (DATA_TYPE*)(B + (i-1)*stride_i);

          for (j = 1; j < n; j++) {
              int nk = n - 2;
              int rem = nk;

              while (rem > 0) {
                  size_t vl = __riscv_vsetvl_e32m1(rem);
                  if (vl == 0) break;

                  // Load vectors
                  // v_minus: A[i][j][0...vl-1] (relative to a_ptr)
                  // v_curr: A[i][j][1...vl] (relative to a_ptr + 1)
                  // v_plus: A[i][j][2...vl+1] (relative to a_ptr + 2)

                  vfloat32m1_t v_minus = __riscv_vle32_vx(a_ptr, vl);
                  vfloat32m1_t v_curr = __riscv_vle32_vx(a_ptr + 1, vl);
                  vfloat32m1_t v_plus = __riscv_vle32_vx(a_ptr + 2, vl);

                  // Compute: B = 0.125 * (A[k+1] + A[k-1]) + 0.25 * A[k]
                  vfloat32m1_t v_sum = __riscv_vfadd_vv(v_plus, v_minus);
                  vfloat32m1_t v_term1 = __riscv_vfmul_vf(v_sum, one_eighth);
                  vfloat32m1_t v_term2 = __riscv_vfmul_vf(v_curr, one_quarter);
                  vfloat32m1_t v_res = __riscv_vfadd_vv(v_term1, v_term2);

                  // Store to B[i][j][1...vl]
                  __riscv_vse32_vx(b_ptr + 1, v_res, vl);

                  rem -= vl;
              }

              a_ptr += stride_j;
              b_ptr += stride_j;
          }
      }

      // Compute A from B
      for (i = 1; i < n; i++) {
          DATA_TYPE *a_ptr = (DATA_TYPE*)(A + (i-1)*stride_i);
          DATA_TYPE *b_ptr = (DATA_TYPE*)(B + (i-1)*stride_i);

          for (j = 1; j < n; j++) {
              int nk = n - 2;
              int rem = nk;

              while (rem > 0) {
                  size_t vl = __riscv_vsetvl_e32m1(rem);
                  if (vl == 0) break;

                  vfloat32m1_t v_minus = __riscv_vle32_vx(b_ptr, vl);
                  vfloat32m1_t v_curr = __riscv_vle32_vx(b_ptr + 1, vl);
                  vfloat32m1_t v_plus = __riscv_vle32_vx(b_ptr + 2, vl);

                  vfloat32m1_t v_sum = __riscv_vfadd_vv(v_plus, v_minus);
                  vfloat32m1_t v_term1 = __riscv_vfmul_vf(v_sum, one_eighth);
                  vfloat32m1_t v_term2 = __riscv_vfmul_vf(v_curr, one_quarter);
                  vfloat32m1_t v_res = __riscv_vfadd_vv(v_term1, v_term2);

                  __riscv_vse32_vx(a_ptr + 1, v_res, vl);

                  rem -= vl;
              }

              a_ptr += stride_j;
              b_ptr += stride_j;
          }
      }
  }
}

