static
void kernel_jacobi_1d(int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_1D(A,N,n),
			    DATA_TYPE POLYBENCH_1D(B,N,n))
{
  int t, i;
  int vlen_i = __riscv_vsetvl_e32m1(n);
  DATA_TYPE alpha = 0.33333;

#pragma scop
  for (t = 0; t < _PB_TSTEPS; t++)
    {
      int rem = _PB_N - 2;
      int vl = __riscv_vsetvl_e32m1(rem);
      vfloat32m1_t vA_prev, vA_curr, vA_next;
      vfloat32m1_t vB_prev, vB_curr, vB_next;
      vfloat32m1_t vSum;
      vfloat32m1_t vAlpha = __riscv_vfmv_v_f(vl, alpha);

      for (i = 1; i < _PB_N - 1; i += vlen_i)
	{
	  vl = __riscv_vsetvl_e32m1(_PB_N - 1 - i);
	  vA_prev = __riscv_vleseg_v_v(vl, A, i - 1);
	  vA_curr = __riscv_vleseg_v_v(vl, A, i);
	  vA_next = __riscv_vleseg_v_v(vl, A, i + 1);

	  vSum = __riscv_vfadd_vv(vl, vA_prev, vA_curr);
	  vSum = __riscv_vfadd_vv(vl, vSum, vA_next);
	  vSum = __riscv_vfmul_vv(vl, vSum, vAlpha);

	  __riscv_vseseg_v_v(vl, B, i, vSum);
	}

      vl = __riscv_vsetvl_e32m1(_PB_N - 2);
      vB_prev = __riscv_vleseg_v_v(vl, B, 0);
      vB_curr = __riscv_vleseg_v_v(vl, B, 1);
      vB_next = __riscv_vleseg_v_v(vl, B, 2);

      vSum = __riscv_vfadd_vv(vl, vB_prev, vB_curr);
      vSum = __riscv_vfadd_vv(vl, vSum, vB_next);
      vSum = __riscv_vfmul_vv(vl, vSum, vAlpha);

      __riscv_vseseg_v_v(vl, A, 1, vSum);
    }
#pragma endscop

}

