static
void kernel_jacobi_2d(int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
			    DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  int t, i, j;
  size_t vl;
  DATA_TYPE *a_ptr, *b_ptr;
  DATA_TYPE *a_next, *b_next;
  DATA_TYPE *a_prev, *b_prev;
  DATA_TYPE *a_curr, *b_curr;
  DATA_TYPE *a_left, *b_left;
  DATA_TYPE *a_right, *b_right;
  DATA_TYPE factor = SCALAR_VAL(0.2);

  // Determine vector length
  size_t max_vl = __riscv_vsetvlmax();
  if (max_vl == 0) max_vl = 1;

  int inner_n = n - 2;
  int vlen_int = (int)max_vl;
  int aligned_n = (inner_n / vlen_int) * vlen_int;
  int remaining = inner_n % vlen_int;

  // Pointer setup for the inner loop region [1..n-2]
  a_ptr = (DATA_TYPE*)A[1];
  b_ptr = (DATA_TYPE*)B[1];

  for (t = 0; t < _PB_TSTEPS; t++)
    {
      // First pass: Update B using A
      for (i = 1; i < _PB_N - 1; i++)
	{
	  a_curr = a_ptr;
	  b_curr = b_ptr;
	  a_prev = (DATA_TYPE*)A[i-1];
	  b_prev = (DATA_TYPE*)B[i-1];
	  a_next = (DATA_TYPE*)A[i+1];
	  b_next = (DATA_TYPE*)B[i+1];
	  a_left = a_curr - 1;
	  b_left = b_curr - 1;
	  a_right = a_curr + 1;
	  b_right = b_curr + 1;

	  // Vectorized loop for columns 1 to aligned_n
	  for (j = 1; j <= aligned_n; j += vlen_int)
	    {
	      vl = __riscv_vsetvl(vlen_int, max_vl);
	      if (vl == 0) vl = 1;

	      // Load operands for A
	      DATA_TYPE *v_a_curr = __riscv_vle8_v(vl, a_curr);
	      DATA_TYPE *v_a_left = __riscv_vle8_v(vl, a_left);
	      DATA_TYPE *v_a_right = __riscv_vle8_v(vl, a_right);
	      DATA_TYPE *v_a_prev = __riscv_vle8_v(vl, a_prev);
	      DATA_TYPE *v_a_next = __riscv_vle8_v(vl, a_next);

	      // Compute sum for A
	      DATA_TYPE *v_sum_a = __riscv_vadd_vv(v_a_curr, v_a_left);
	      v_sum_a = __riscv_vadd_vv(v_sum_a, v_a_right);
	      v_sum_a = __riscv_vadd_vv(v_sum_a, v_a_prev);
	      v_sum_a = __riscv_vadd_vv(v_sum_a, v_a_next);

	      // Multiply by 0.2
	      v_sum_a = __riscv_vfmul_vf(v_sum_a, factor);

	      // Store to B
	      __riscv_vse8_v(v_sum_a, b_curr);
	    }

	  // Handle remaining elements if any
	  if (remaining > 0)
	    {
	      size_t rem_vl = remaining;
	      if (rem_vl > max_vl) rem_vl = max_vl;
	      vl = rem_vl;

	      a_curr += aligned_n;
	      b_curr += aligned_n;
	      a_left += aligned_n;
	      b_left += aligned_n;
	      a_right += aligned_n;
	      b_right += aligned_n;
	      a_prev += aligned_n;
	      b_prev += aligned_n;
	      a_next += aligned_n;
	      b_next += aligned_n;

	      DATA_TYPE *v_a_curr = __riscv_vle8_v(vl, a_curr);
	      DATA_TYPE *v_a_left = __riscv_vle8_v(vl, a_left);
	      DATA_TYPE *v_a_right = __riscv_vle8_v(vl, a_right);
	      DATA_TYPE *v_a_prev = __riscv_vle8_v(vl, a_prev);
	      DATA_TYPE *v_a_next = __riscv_vle8_v(vl, a_next);

	      DATA_TYPE *v_sum_a = __riscv_vadd_vv(v_a_curr, v_a_left);
	      v_sum_a = __riscv_vadd_vv(v_sum_a, v_a_right);
	      v_sum_a = __riscv_vadd_vv(v_sum_a, v_a_prev);
	      v_sum_a = __riscv_vadd_vv(v_sum_a, v_a_next);

	      v_sum_a = __riscv_vfmul_vf(v_sum_a, factor);

	      __riscv_vse8_v(v_sum_a, b_curr);
	    }

	  // Move to next row
	  a_ptr += n;
	  b_ptr += n;
	}

      // Second pass: Update A using B
      for (i = 1; i < _PB_N - 1; i++)
	{
	  a_curr = a_ptr;
	  b_curr = b_ptr;
	  a_prev = (DATA_TYPE*)A[i-1];
	  b_prev = (DATA_TYPE*)B[i-1];
	  a_next = (DATA_TYPE*)A[i+1];
	  b_next = (DATA_TYPE*)B[i+1];
	  a_left = a_curr - 1;
	  b_left = b_curr - 1;
	  a_right = a_curr + 1;
	  b_right = b_curr + 1;

	  for (j = 1; j <= aligned_n; j += vlen_int)
	    {
	      vl = __riscv_vsetvl(vlen_int, max_vl);
	      if (vl == 0) vl = 1;

	      DATA_TYPE *v_b_curr = __riscv_vle8_v(vl, b_curr);
	      DATA_TYPE *v_b_left = __riscv_vle8_v(vl, b_left);
	      DATA_TYPE *v_b_right = __riscv_vle8_v(vl, b_right);
	      DATA_TYPE *v_b_prev = __riscv_vle8_v(vl, b_prev);
	      DATA_TYPE *v_b_next = __riscv_vle8_v(vl, b_next);

	      DATA_TYPE *v_sum_b = __riscv_vadd_vv(v_b_curr, v_b_left);
	      v_sum_b = __riscv_vadd_vv(v_sum_b, v_b_right);
	      v_sum_b = __riscv_vadd_vv(v_sum_b, v_b_prev);
	      v_sum_b = __riscv_vadd_vv(v_sum_b, v_b_next);

	      v_sum_b = __riscv_vfmul_vf(v_sum_b, factor);

	      __riscv_vse8_v(v_sum_b, a_curr);
	    }

	  if (remaining > 0)
	    {
	      size_t rem_vl = remaining;
	      if (rem_vl > max_vl) rem_vl = max_vl;
	      vl = rem_vl;

	      a_curr += aligned_n;
	      b_curr += aligned_n;
	      a_left += aligned_n;
	      b_left += aligned_n;
	      a_right += aligned_n;
	      b_right += aligned_n;
	      a_prev += aligned_n;
	      b_prev += aligned_n;
	      a_next += aligned_n;
	      b_next += aligned_n;

	      DATA_TYPE *v_b_curr = __riscv_vle8_v(vl, b_curr);
	      DATA_TYPE *v_b_left = __riscv_vle8_v(vl, b_left);
	      DATA_TYPE *v_b_right = __riscv_vle8_v(vl, b_right);
	      DATA_TYPE *v_b_prev = __riscv_vle8_v(vl, b_prev);
	      DATA_TYPE *v_b_next = __riscv_vle8_v(vl, b_next);

	      DATA_TYPE *v_sum_b = __riscv_vadd_vv(v_b_curr, v_b_left);
	      v_sum_b = __riscv_vadd_vv(v_sum_b, v_b_right);
	      v_sum_b = __riscv_vadd_vv(v_sum_b, v_b_prev);
	      v_sum_b = __riscv_vadd_vv(v_sum_b, v_b_next);

	      v_sum_b = __riscv_vfmul_vf(v_sum_b, factor);

	      __riscv_vse8_v(v_sum_b, a_curr);
	    }

	  a_ptr += n;
	  b_ptr += n;
	}
    }
}

