static
void kernel_ludcmp(int n,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(b,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j, k;
  DATA_TYPE w;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    for (j = 0; j < i; j++) {
       w = A[i][j];
#if defined(__riscv_vector)
       if (j > 0) {
          int vl = __riscv_vsetvl_e32f(j);
          vfloat32m1_t vA_i = __riscv_vleig_v_fvm_a32(&A[i][0], vl);
          vfloat32m1_t vA_kj = __riscv_vleig_v_fvm_a32(&A[0][j], vl);
          vfloat32m1_t vprod = __riscv_vfmacc_v_fvm_v_fvm_a32(vA_i, vA_kj, vl);
          vfloat32m1_t vzero = __riscv_vfmv_v_f_v(0.0f, vl);
          vfloat32m1_t vsub = __riscv_vfsub_vv_fvm_v_fvm_a32(vzero, vprod, vl);
          __riscv_vseig_v_fvm_a32(&w, vsub, vl);
       }
#else
       for (k = 0; k < j; k++) {
          w -= A[i][k] * A[k][j];
       }
#endif
        A[i][j] = w / A[j][j];
    }
   for (j = i; j < _PB_N; j++) {
       w = A[i][j];
#if defined(__riscv_vector)
       if (i > 0) {
          int vl = __riscv_vsetvl_e32f(i);
          vfloat32m1_t vA_i = __riscv_vleig_v_fvm_a32(&A[i][0], vl);
          vfloat32m1_t vA_kj = __riscv_vleig_v_fvm_a32(&A[0][j], vl);
          vfloat32m1_t vprod = __riscv_vfmacc_v_fvm_v_fvm_a32(vA_i, vA_kj, vl);
          vfloat32m1_t vzero = __riscv_vfmv_v_f_v(0.0f, vl);
          vfloat32m1_t vsub = __riscv_vfsub_vv_fvm_v_fvm_a32(vzero, vprod, vl);
          __riscv_vseig_v_fvm_a32(&w, vsub, vl);
       }
#else
       for (k = 0; k < i; k++) {
          w -= A[i][k] * A[k][j];
       }
#endif
       A[i][j] = w;
    }
  }

  for (i = 0; i < _PB_N; i++) {
     w = b[i];
#if defined(__riscv_vector)
     if (i > 0) {
        int vl = __riscv_vsetvl_e32f(i);
        vfloat32m1_t vA_i = __riscv_vleig_v_fvm_a32(&A[i][0], vl);
        vfloat32m1_t vy = __riscv_vleig_v_fvm_a32(&y[0], vl);
        vfloat32m1_t vprod = __riscv_vfmacc_v_fvm_v_fvm_a32(vA_i, vy, vl);
        vfloat32m1_t vzero = __riscv_vfmv_v_f_v(0.0f, vl);
        vfloat32m1_t vsub = __riscv_vfsub_vv_fvm_v_fvm_a32(vzero, vprod, vl);
        __riscv_vseig_v_fvm_a32(&w, vsub, vl);
     }
#else
     for (j = 0; j < i; j++)
        w -= A[i][j] * y[j];
#endif
     y[i] = w;
  }

   for (i = _PB_N-1; i >=0; i--) {
     w = y[i];
#if defined(__riscv_vector)
     if (i < _PB_N - 1) {
        int vl = __riscv_vsetvl_e32f(_PB_N - 1 - i);
        vfloat32m1_t vA_i = __riscv_vleig_v_fvm_a32(&A[i][i+1], vl);
        vfloat32m1_t vx = __riscv_vleig_v_fvm_a32(&x[i+1], vl);
        vfloat32m1_t vprod = __riscv_vfmacc_v_fvm_v_fvm_a32(vA_i, vx, vl);
        vfloat32m1_t vzero = __riscv_vfmv_v_f_v(0.0f, vl);
        vfloat32m1_t vsub = __riscv_vfsub_vv_fvm_v_fvm_a32(vzero, vprod, vl);
        __riscv_vseig_v_fvm_a32(&w, vsub, vl);
     }
#else
     for (j = i+1; j < _PB_N; j++)
        w -= A[i][j] * x[j];
#endif
     x[i] = w / A[i][i];
  }
#pragma endscop

}

