static
void kernel_mvt(int n,
		DATA_TYPE POLYBENCH_1D(x1,N,n),
		DATA_TYPE POLYBENCH_1D(x2,N,n),
		DATA_TYPE POLYBENCH_1D(y_1,N,n),
		DATA_TYPE POLYBENCH_1D(y_2,N,n),
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;
  size_t vl;

#pragma scop
  // Determine vector length
  vl = __riscv_vsetvl_e32m1(n);

  // First loop: x1[i] += sum_j(A[i][j] * y_1[j])
  // This is a row-wise dot product. We can vectorize the inner loop over j.
  for (i = 0; i < n; i++) {
    DATA_TYPE acc = x1[i];
    DATA_TYPE *a_row = &A[i][0];
    DATA_TYPE *y_ptr = &y_1[0];

    // Initialize vector registers
    vfloat32m1_t va = __riscv_vleig_vx(vl, a_row);
    vfloat32m1_t vy = __riscv_vleig_vx(vl, y_ptr);
    vfloat32m1_t vzero = __riscv_vfmv_v_f(vl, (float)0.0);

    // Accumulate dot product
    vfloat32m1_t vsum = vzero;
    for (j = 0; j < n; j += vl) {
      size_t vlen = __riscv_vsetvl_e32m1(n - j);
      vfloat32m1_t va_chunk = __riscv_vleig_vx(vlen, &a_row[j]);
      vfloat32m1_t vy_chunk = __riscv_vleig_vx(vlen, &y_ptr[j]);

      vfloat32m1_t vprod = __riscv_vfmul_vv(vlen, va_chunk, vy_chunk);
      vsum = __riscv_vfadd_vv(vlen, vsum, vprod);
    }

    // Add accumulator to result
    DATA_TYPE res = __riscv_vfmv_f_v(vl, vsum);
    x1[i] = acc + res;
  }

  // Second loop: x2[i] += sum_j(A[j][i] * y_2[j])
  // This is a column-wise dot product. We can vectorize the inner loop over j.
  for (i = 0; i < n; i++) {
    DATA_TYPE acc = x2[i];
    DATA_TYPE *y_ptr = &y_2[0];

    // Initialize vector registers
    vfloat32m1_t vy = __riscv_vleig_vx(vl, y_ptr);
    vfloat32m1_t vzero = __riscv_vfmv_v_f(vl, (float)0.0);

    // Accumulate dot product
    vfloat32m1_t vsum = vzero;
    for (j = 0; j < n; j += vl) {
      size_t vlen = __riscv_vsetvl_e32m1(n - j);
      DATA_TYPE *a_col = &A[j][i];
      vfloat32m1_t va_chunk = __riscv_vleig_vx(vlen, a_col);
      vfloat32m1_t vy_chunk = __riscv_vleig_vx(vlen, &y_ptr[j]);

      vfloat32m1_t vprod = __riscv_vfmul_vv(vlen, va_chunk, vy_chunk);
      vsum = __riscv_vfadd_vv(vlen, vsum, vprod);
    }

    // Add accumulator to result
    DATA_TYPE res = __riscv_vfmv_f_v(vl, vsum);
    x2[i] = acc + res;
  }
#pragma endscop
}

