static
void kernel_nussinov(int n, base POLYBENCH_1D(seq,N,n),
			   DATA_TYPE POLYBENCH_2D(table,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (i = n-1; i >= 0; i--) {
    for (j = i+1; j < n; j++) {
      DATA_TYPE val = table[i][j];

      if (j-1 >= 0) {
        val = max_score(val, table[i][j-1]);
      }
      if (i+1 < n) {
        val = max_score(val, table[i+1][j]);
      }

      if (j-1 >= 0 && i+1 < n) {
        DATA_TYPE diag = table[i+1][j-1];
        if (i < j-1) {
          DATA_TYPE match_val = diag + match(seq[i], seq[j]);
          val = max_score(val, match_val);
        } else {
          val = max_score(val, diag);
        }
      }

      // Vectorized loop for k from i+1 to j-1
      if (j > i + 1) {
        int count = j - (i + 1);
        int vl = __riscv_vsetvl_e8m1(count);

        // Pointers to the start of the vector segments
        vint8m1_t *vbase1 = (vint8m1_t *)(&table[i][i+1]);
        vint8m1_t *vbase2 = (vint8m1_t *)(&table[i+2][j]);
        vint8m1_t *vres_ptr = (vint8m1_t *)(&table[i][j]);

        // We need to compute max over k of (table[i][k] + table[k+1][j])
        // Since this is a reduction (max over a range), we cannot fully vectorize
        // the accumulation into a single register without a reduction instruction.
        // However, we can vectorize the loading and adding, then reduce.
        // Given the small loop size (j-i is typically small in Nussinov),
        // a simple scalar loop with potential unrolling or just clean code is often best.
        // But to attempt vectorization, we will load vectors, add them, and reduce.

        // Strategy: Load vectors of (table[i][k] + table[k+1][j]), find max in vector, then reduce.
        // Since we need the max of the sum, we can do:
        // 1. Load v1 = table[i][k]
        // 2. Load v2 = table[k+1][j]
        // 3. vsum = v1 + v2
        // 4. vmax = max(vsum, current_max)
        // Repeat.

        // Actually, for a reduction loop, the most efficient vector approach is often
        // to just use a scalar loop if the trip count is small, or use a reduction intrinsic
        // if available. Let's try a simple scalar loop first to ensure correctness,
        // but optimized with vector loads if possible.
        // However, the requirement is to use vector techniques.
        // Let's implement a loop that uses vector loads for the operands.

        for (int k_vec = 0; k_vec < count; k_vec++) {
          int k = i + 1 + k_vec;
          // Load table[i][k] and table[k+1][j]
          // We can't easily vectorize a single iteration's load unless we batch.
          // Let's try to batch 4 iterations.
          if (k_vec % 4 == 0) {
             int rem = count - k_vec;
             int vlen = __riscv_vsetvl_e8m1(rem);
             vint8m1_t *v1 = __riscv_vload_vx(vlen, (vint8m1_t*)(&table[i][i+1+k_vec]), 0);
             vint8m1_t *v2 = __riscv_vload_vx(vlen, (vint8m1_t*)(&table[i+2+k_vec][j]), 0);
             vint8m1_t *vsum = __riscv_vadd_vv(v1, v2, vlen);

             // Now we need to reduce this vector against 'val'
             // We can't do a full reduction in one step easily without a loop over the vector.
             // So we fall back to scalar reduction for the vector result.
             for (int idx = 0; idx < vlen; idx++) {
                DATA_TYPE s = (DATA_TYPE)__riscv_vle8_vx(vsum, idx);
                val = max_score(val, s);
             }
          } else {
             int k = i + 1 + k_vec;
             val = max_score(val, table[i][k] + table[k+1][j]);
          }
        }
      }

      table[i][j] = val;
    }
  }
#pragma endscop
}

