static
void kernel_seidel_2d(int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int t, i, j;
  vfloat32m1_t v9;
  vfloat32m1_t vone;
  vfloat32m1_t vzero;

  v9 = __riscv_vfmv_v_f_x(vfloat32m1(9.0));
  vone = __riscv_vfmv_v_f_x(vfloat32m1(1.0));
  vzero = __riscv_vfmv_v_f_x(vfloat32m1(0.0));

#pragma scop
  for (t = 0; t <= _PB_TSTEPS - 1; t++)
    for (i = 1; i <= _PB_N - 2; i++) {
      int vl = __riscv_vsetvl_e32m1();
      vuint32m1_t vi = __riscv_vmv_v_x_u(vl, i);
      vuint32m1_t vi1 = __riscv_vadd_vv(vl, vi, vone);
      vuint32m1_t vi2 = __riscv_vadd_vv(vl, vi1, vone);
      vuint32m1_t vi0 = __riscv_vsub_vv(vl, vi, vone);
      vuint32m1_t vi_1 = __riscv_vsub_vv(vl, vi0, vone);

      for (j = 1; j <= _PB_N - 2; j++) {
        int vl = __riscv_vsetvl_e32m1();
        vuint32m1_t vj = __riscv_vmv_v_x_u(vl, j);
        vuint32m1_t vj1 = __riscv_vadd_vv(vl, vj, vone);
        vuint32m1_t vj2 = __riscv_vadd_vv(vl, vj1, vone);
        vuint32m1_t vj0 = __riscv_vsub_vv(vl, vj, vone);
        vuint32m1_t vj_1 = __riscv_vsub_vv(vl, vj0, vone);

        vfloat32m1_t va_i_j_1 = __riscv_vleaf_v_v_f(vl, A, vi_1, vj);
        vfloat32m1_t va_i_j = __riscv_vleaf_v_v_f(vl, A, vi, vj);
        vfloat32m1_t va_i_j_1_1 = __riscv_vleaf_v_v_f(vl, A, vi_1, vj1);
        vfloat32m1_t va_i_j_1_2 = __riscv_vleaf_v_v_f(vl, A, vi_1, vj2);
        vfloat32m1_t va_i_j_0_1 = __riscv_vleaf_v_v_f(vl, A, vi0, vj1);
        vfloat32m1_t va_i_j_0_2 = __riscv_vleaf_v_v_f(vl, A, vi0, vj2);
        vfloat32m1_t va_i_j_0 = __riscv_vleaf_v_v_f(vl, A, vi0, vj);
        vfloat32m1_t va_i_j_1_0 = __riscv_vleaf_v_v_f(vl, A, vi_1, vj0);
        vfloat32m1_t va_i_j_0_0 = __riscv_vleaf_v_v_f(vl, A, vi0, vj0);

        vfloat32m1_t sum = __riscv_vadd_vv(vl, va_i_j_1_1, va_i_j_1_2);
        sum = __riscv_vadd_vv(vl, sum, va_i_j_1_0);
        sum = __riscv_vadd_vv(vl, sum, va_i_j_1);
        sum = __riscv_vadd_vv(vl, sum, va_i_j_0_1);
        sum = __riscv_vadd_vv(vl, sum, va_i_j_0_2);
        sum = __riscv_vadd_vv(vl, sum, va_i_j_0);
        sum = __riscv_vadd_vv(vl, sum, va_i_j_1_0);
        sum = __riscv_vadd_vv(vl, sum, va_i_j_0_0);
        sum = __riscv_vadd_vv(vl, sum, va_i_j);

        vfloat32m1_t vinv9 = __riscv_vdiv_vv(vl, vone, v9);
        vfloat32m1_t new_val = __riscv_vfmul_vv(vl, sum, vinv9);

        __riscv_vseaf_v_v_f(vl, A, vi, vj, new_val);
      }
    }
#pragma endscop
}

