static
void kernel_symm(int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;
  DATA_TYPE temp2;
  DATA_TYPE *C_ptr, *A_ptr, *B_ptr;
  DATA_TYPE *C_row, *A_row, *B_col;
  size_t vl;

#pragma scop
   for (i = 0; i < _PB_M; i++)
      for (j = 0; j < _PB_N; j++ )
      {
        temp2 = 0;
        C_ptr = (DATA_TYPE*)C;
        A_ptr = (DATA_TYPE*)A;
        B_ptr = (DATA_TYPE*)B;
        C_row = C_ptr + i * _PB_N + j;
        A_row = A_ptr + i * _PB_M;
        B_col = B_ptr + i * _PB_N + j;

        vl = __riscv_vsetvl_e32m1(i);
        vfloat32m1_t vtemp2_vec = __riscv_vmv_v_x_f32m1(0.0f, vl);

        for (k = 0; k < i; k++) {
           DATA_TYPE b_val = B_col[k];
           DATA_TYPE a_val = A_row[k];
           DATA_TYPE prod = b_val * a_val;

           vfloat32m1_t vprod = __riscv_vfmv_v_f_f32m1(prod, vl);
           vtemp2_vec = __riscv_vfadd_vv_f32m1(vtemp2_vec, vprod, vl);

           __riscv_vfadd_vx_f32m1(C_row, prod, vl);
        }

        DATA_TYPE c_val = C_row[0];
        DATA_TYPE a_diag = A_row[i];
        DATA_TYPE b_diag = B_col[0];

        DATA_TYPE final_val = beta * c_val + alpha * b_diag * a_diag + alpha * __riscv_vfmv_f_v_f32m1(vtemp2_vec, 0);
        C_row[0] = final_val;
     }
#pragma endscop

}

