static
void kernel_syr2k(int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;
  size_t vl;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    // Apply beta to C[i][0..i]
    for (j = 0; j <= i; j++) {
      DATA_TYPE val = C[i][j];
      vl = __riscv_vsetvlmax();
      vfloatm_t vval = __riscv_vfmv_v_f(vl, val);
      vfloatm_t vbeta = __riscv_vfmv_v_f(vl, beta);
      vfloatm_t vres = __riscv_vfmul_v_f(vl, vval, vbeta);
      __riscv_vfmv_f_f(vl, vres);
      C[i][j] = vres;
    }

    // Vectorized inner loop over k
    for (k = 0; k < _PB_M; k += vl) {
      vl = __riscv_vsetvl(vl, m - k);
      if (vl == 0) continue;

      // Load A[i] and B[i] segments
      vfloatm_t vA_i = __riscv_vleop_v_f(m_vec, A[i] + k, vl);
      vfloatm_t vB_i = __riscv_vleop_v_f(m_vec, B[i] + k, vl);

      // Pre-multiply by alpha
      vfloatm_t vA_i_alpha = __riscv_vfmul_v_f(vl, vA_i, __riscv_vfmv_v_f(vl, alpha));
      vfloatm_t vB_i_alpha = __riscv_vfmul_v_f(vl, vB_i, __riscv_vfmv_v_f(vl, alpha));

      for (j = 0; j <= i; j++) {
         // Load A[j][k] and B[j][k]
         DATA_TYPE A_jk = A[j][k];
         DATA_TYPE B_jk = B[j][k];

         // Compute: A[j][k]*alpha*B[i][k] + B[j][k]*alpha*A[i][k]
         // = A[j][k] * (B[i][k] * alpha) + B[j][k] * (A[i][k] * alpha)

         DATA_TYPE term1 = A_jk * __riscv_vfmv_f_f(vl, vB_i_alpha);
         DATA_TYPE term2 = B_jk * __riscv_vfmv_f_f(vl, vA_i_alpha);
         DATA_TYPE sum = term1 + term2;
         DATA_TYPE contrib = sum;

         C[i][j] += contrib;
      }
    }
  }
#pragma endscop
}

