static
void kernel_syrk(int n, int m,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j, k;
  int vl = __riscv_vsetvlmax();

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    // Scale C[i][0..i] by beta
    for (j = 0; j <= i; j++) {
      vfloat32_t c_val = __riscv_vleif_v_f(vl, (float)C[i][j], vl);
      vfloat32_t beta_v = __riscv_vfmv_v_f(vl, (float)beta);
      vfloat32_t res = __riscv_vfmul_vv(c_val, beta_v);
      __riscv_vseif_v_f(vl, (float)C[i][j], res, vl);
    }

    // Compute the sum over k
    for (k = 0; k < _PB_M; k++) {
      vfloat32_t a_i_val = __riscv_vleif_v_f(vl, (float)A[i][k], vl);

      // Process j from 0 to i
      for (j = 0; j <= i; j++) {
        vfloat32_t a_j_val = __riscv_vleif_v_f(vl, (float)A[j][k], vl);
        vfloat32_t prod = __riscv_vfmul_vv(a_i_val, a_j_val);
        prod = __riscv_vfmul_vf(prod, (float)alpha);

        vfloat32_t c_val = __riscv_vleif_v_f(vl, (float)C[i][j], vl);
        vfloat32_t res = __riscv_vfadd_vv(c_val, prod);
        __riscv_vseif_v_f(vl, (float)C[i][j], res, vl);
      }
    }
  }
#pragma endscop
}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

static
void kernel_trisolv(int n,
		    DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;
  size_t vl;

#pragma scop
  // Determine vector length
  vl = __riscv_vsetvl_e32m1(n);

  for (i = 0; i < _PB_N; i++)
    {
      // Load b[i] into a scalar register
      DATA_TYPE val = b[i];

      // Initialize vector with val
      vfloat32m1_t vx = __riscv_vfmv_v_f(vl, val);

      // Loop over j < i
      for (j = 0; j < i; j++)
        {
          // Load L[i][j]
          DATA_TYPE L_ij = L[i][j];
          vfloat32m1_t v_Lij = __riscv_vfmv_v_f(vl, L_ij);

          // Load x[j]
          DATA_TYPE x_j = x[j];
          vfloat32m1_t v_xj = __riscv_vfmv_v_f(vl, x_j);

          // Multiply: L[i][j] * x[j]
          vfloat32m1_t v_prod = __riscv_vfmul_vv(vx, v_Lij, vl);

          // Subtract from x[i]: x[i] -= L[i][j] * x[j]
          vx = __riscv_vfsub_vv(vx, v_prod, vl);
        }

      // Normalize: x[i] = x[i] / L[i][i]
      DATA_TYPE L_ii = L[i][i];
      vfloat32m1_t v_Lii = __riscv_vfmv_v_f(vl, L_ii);
      vx = __riscv_vfdiv_vv(vx, v_Lii, vl);

      // Store result back to x[i]
      x[i] = __riscv_vfmv_f_v(vl, vx);
    }
#pragma endscop

}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

static
void kernel_trmm(int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;
  int vl = 0;

#pragma scop
  for (i = 0; i < _PB_M; i++) {
    for (j = 0; j < _PB_N; j++) {
      DATA_TYPE sum = B[i][j];
      int k_start = i + 1;
      int k_end = _PB_M;

      // Vectorized accumulation for k loop
      for (k = k_start; k < k_end; k += vl) {
        vl = __riscv_vsetvl(k_end - k, vl);
        vfloat32m1_t va = __riscv_vleifft_vx(vl, A[k][i]);
        vfloat32m1_t vb = __riscv_vleifft_vx(vl, B[k][j]);
        vfloat32m1_t vand = __riscv_vmul_vv(va, vb);
        sum += __riscv_vfmadd_vf(vand, alpha, sum);
      }
      B[i][j] = sum;
    }
  }
#pragma endscop
}
